// Duas buscas na Gupy: estágios no Ceará e estágios remotos
const base = 'https://portal.gupy.io/api/job-search/jobs?jobName=' + encodeURIComponent('estágio') + '&limit=100&offset=0';
return [
  { json: { busca: 'Ceará', url: base + '&state=' + encodeURIComponent('Ceará') } },
  { json: { busca: 'Remoto', url: base + '&workplaceType=remote' } },
];

// Junta os resultados de todas as buscas e mantém só vagas relevantes
const vistos = new Set();
const saida = [];
const limite = Date.now() - 7 * 24 * 60 * 60 * 1000; // publicadas nos últimos 7 dias
// Só manda para a IA vagas que mencionam áreas compatíveis com Engenharia Elétrica
const areas = ['engenharia', 'eletric', 'exatas', 'tecnologia', 'dados', 'computacao', 'automacao',
  'qualquer curso', 'todos os cursos', 'diversos cursos', 'qualquer area', 'todas as areas'];
const semAcento = t => t.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

for (const item of $input.all()) {
  for (const v of (item.json.data || [])) {
    if (vistos.has(v.id)) continue;
    vistos.add(v.id);
    if (v.type !== 'vacancy_type_internship') continue;          // só estágio
    const local = v.state === 'Ceará' || v.workplaceType === 'remote';
    if (!local) continue;                                          // Ceará ou remoto
    if (new Date(v.publishedDate).getTime() < limite) continue;    // só recentes
    const descricao = String(v.description || '')
      .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim()
      .slice(0, 4000);
    const texto = semAcento(v.name + ' ' + descricao);
    if (!areas.some(a => texto.includes(a))) continue;            // área compatível
    saida.push({ json: {
      id: v.id, titulo: v.name, empresa: v.careerPageName,
      cidade: v.city, estado: v.state, modelo: v.workplaceType,
      prazo: v.applicationDeadline, publicada: v.publishedDate,
      link: v.jobUrl, descricao,
    }});
  }
}
return saida;

// Junta a resposta da IA com os dados da vaga e descarta as não compatíveis
const vagas = $('Remover já vistas').all();
const respostas = $input.all();
const saida = [];
respostas.forEach((r, i) => {
  const texto = String(r.json.text || '').replace(/```json|```/g, '').trim();
  let a;
  try { a = JSON.parse(texto.slice(texto.indexOf('{'), texto.lastIndexOf('}') + 1)); }
  catch (e) { a = { veredito: 'erro na análise', motivo: texto.slice(0, 200), atende: [], nao_atende: [], lacunas: [] }; }
  if (a.veredito === 'não candidatar') return;
  saida.push({ json: { ...vagas[i].json, ...a } });
});
return saida;

// Monta o e-mail com as vagas compatíveis
const vagas = $input.all().map(i => i.json);
if (vagas.length === 0) return [];
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const lista = arr => (arr && arr.length) ? '<ul>' + arr.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '<p>-</p>';
const cor = v => v === 'candidatar' ? '#1a7f37' : '#9a6700';
const blocos = vagas.map(v => `
  <div style="border:1px solid #ddd;border-radius:8px;padding:16px;margin:0 0 16px">
    <div style="font-size:12px;color:${cor(v.veredito)};font-weight:bold;text-transform:uppercase">${esc(v.veredito)}</div>
    <h3 style="margin:4px 0">${esc(v.titulo)}</h3>
    <div style="color:#555">${esc(v.empresa)} · ${esc(v.cidade)}/${esc(v.estado)} · ${esc(v.modelo)}${v.prazo ? ' · inscrições até ' + new Date(v.prazo).toLocaleDateString('pt-BR') : ''}</div>
    <p>${esc(v.motivo)}</p>
    <b>Atendo</b>${lista(v.atende)}
    <b>Pontos de atenção</b>${lista(v.nao_atende)}
    <b>Lacunas</b>${lista(v.lacunas)}
    <a href="${esc(v.link)}">Abrir a vaga</a>
  </div>`).join('');
const html = `<div style="font-family:Arial,sans-serif;max-width:640px">
  <h2>${vagas.length} vaga(s) de estágio compatível(is) hoje</h2>${blocos}
  <p style="color:#888;font-size:12px">Monitor de vagas · n8n + IA · Gabriel Souza</p></div>`;
return [{ json: { assunto: `Monitor de vagas: ${vagas.length} vaga(s) compatível(is)`, html } }];
